import java.util.Scanner;

public class Main {

    public void solve() {
        Scanner scanner = new Scanner(System.in);
        long W = scanner.nextLong();
        long M = scanner.nextLong();
        int powerIndex = 0;
        while (Math.pow(W, powerIndex) < M) {
            powerIndex++;
        }
        if (Math.pow(W, powerIndex) == M) {
            System.out.println("YES");
            return;
        }

        long maxPower = (long) Math.pow(W, powerIndex);
        long sumSeries = (maxPower - 1) / (W - 1);
        if (maxPower - sumSeries == M) {
            System.out.println("YES");
            return;
        }
        if (isDivisibleChain(W, M)) {
            System.out.println("YES");
        } else {
            System.out.println("NO");
        }
    }

    private boolean isDivisibleChain(long W, long M) {
        if (M == 1) {
            return true;
        }
        if (M % W == 0) {
            return isDivisibleChain(W, M / W);
        } else if ((M - 1) % W == 0) {
            return isDivisibleChain(W, (M - 1) / W);
        } else if ((M + 1) % W == 0) {
            return isDivisibleChain(W, (M + 1) / W);
        }
        return false;
    }

    public static void main(String[] args) {
        new Main().solve();
    }
}
